def create_legacy_provenance(apps, schema_editor):
    del schema_editor
    for run_model, provenance_model in (
        ("TreasuryGLReconciliationRun", "TreasuryGLReconciliationRunProvenance"),
        ("BankReconciliationRun", "BankReconciliationRunProvenance"),
    ):
        Run = apps.get_model("treasury", run_model)
        Provenance = apps.get_model("treasury", provenance_model)
        for run in Run.objects.iterator():
            Provenance.objects.get_or_create(
                run_id=run.pk,
                defaults={
                    "classification": "legacy_unverified",
                    "evidence_hash": run.evidence_hash,
                },
            )


